import {esc,num,money,dimensionLabel} from './view.js';
import {authorize,fetchSearchReport,loadGoogle} from './search-console.js';
const unwrap=r=>{if(r?.err)throw new Error(Object.values(r.err)[0]||Object.keys(r.err)[0]);return r?.ok??r;};
const rate=(n,d)=>Number(d)?(100*Number(n)/Number(d)).toFixed(1)+'%':'—';
const revenue=values=>values.length?values.map(([c,n])=>money(c,n)).join(' · '):'—';
export const csvCell=value=>{let text=String(value??'');if(/^[\s\uFEFF]*[=+@-]|^[\t\r\n]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
export function downloadReport(rows,name){const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function businessWorkspace(ctx){
 const $=id=>document.getElementById(id),call=(method,...args)=>ctx.actor()[method](ctx.token(),...args).then(unwrap);
 let saved=[],connection,reportRows=[],requestVersion=0,preparedSearch;
 const alive=run=>ctx.isCurrent(run),showError=e=>ctx.notice(e.message);
 function fullTable(rows,dimension,{currency=false}={}){
  if(!rows.length)return '<p class="empty-report">No data for these dates and filters.</p>';
  return `<div class="table-scroll"><table class="analytics-table"><thead><tr><th>${esc(dimensionLabel(dimension))}</th><th>Visitors</th><th>Visits</th><th>Pageviews</th><th>Events</th><th>Scroll</th><th>Revenue</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="text-button" data-filter="${esc(dimension)}" data-value="${esc(r.value)}">${esc(r.value||'Direct / unknown')}</button></td><td>${num(r.metrics.visitors)}</td><td>${num(r.metrics.visits)}</td><td>${num(r.metrics.pageviews)}</td><td>${num(r.metrics.events)}</td><td>${Number(r.metrics.scrollSamples)?(Number(r.metrics.scrollDepthSum)/Number(r.metrics.scrollSamples)).toFixed(0)+'%':'—'}</td><td>${esc(revenue(r.metrics.revenue))}</td></tr>`).join('')}</tbody></table></div>`;
 }
 async function savedControls(run){
  const rows=await call('savedReports',ctx.site().id);if(!alive(run))return;saved=rows;const selected=$('savedReport').value;
  $('savedReport').innerHTML='<option value="">Saved filters & funnels</option>'+saved.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}${r.steps.length?' · Funnel':''}</option>`).join('');if(saved.some(r=>r.id===selected))$('savedReport').value=selected;
 }
 $('savedReport').onchange=()=>{const r=saved.find(r=>r.id===$('savedReport').value);if(r)ctx.applySaved(r);};
 $('saveView').onclick=()=>{$('savedTools').open=false;$('saveReportForm').hidden=false;ctx.dirty(true);$('savedName').focus();};
 $('cancelSaveReport').onclick=()=>{$('saveReportForm').hidden=true;ctx.dirty(false);$('savedTools').querySelector('summary').focus();};
 $('saveReportForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(button.disabled)return;button.disabled=true;const run=ctx.epoch();try{const item={id:crypto.randomUUID(),site:ctx.site().id,name:$('savedName').value.trim(),filters:ctx.request().filters,steps:$('saveFunnel').checked?ctx.steps():[],revision:0n,updatedAt:0n};await call('saveReport',item);if(!alive(run))return;$('saveReportForm').hidden=true;ctx.dirty(false);$('savedName').value='';await savedControls(run);ctx.notice('Saved. Everyone with access to this website can use this view.','success');}catch(e){if(alive(run))showError(e);}finally{button.disabled=false;}};
 $('manageSaved').onclick=()=>{$('savedTools').open=false;$('savedReportList').hidden=!$('savedReportList').hidden;$('savedReportList').innerHTML=saved.length?saved.map(r=>`<div class="data-row"><span>${esc(r.name)}</span><button data-delete-saved="${esc(r.id)}">Remove</button></div>`).join(''):'<p class="subtle">No saved filters yet.</p>';if(!$('savedReportList').hidden)$('savedReportList').focus();else $('savedTools').querySelector('summary').focus();};
 $('savedReportList').onclick=async e=>{const run=ctx.epoch(),button=e.target.closest('[data-delete-saved]'),r=saved.find(r=>r.id===button?.dataset.deleteSaved);if(!r)return;if(!await ctx.confirm('Remove '+r.name+'?','Collected data is retained.','Remove filters'))return;button.disabled=true;try{await call('deleteReport',r.site,r.id,r.revision);if(!alive(run))return;await savedControls(run);$('savedReportList').hidden=true;}catch(e){showError(e);}finally{button.disabled=false;}};
 async function acquisition(run){
  const dimension=$('acquisitionDimension').value,r=ctx.request(dimension,1000);if(dimension==='aiSource')r.filters.push({dimension:'aiSource',values:[''],exclude:true});const data=await call('report',r);if(!alive(run))return;
  reportRows=data.rows;$('acquisitionRows').innerHTML=fullTable(data.rows,dimension);$('acquisitionNote').textContent=(data.truncated?'Top 1,000 groups shown. ':'')+(dimension==='aiSource'?'Recognized referring AI services. Missing referrers remain unknown; these are website visits, not AI crawler counts.':'Attribution uses the first event of each visit. Campaign labels take precedence where supplied.');
 }
 $('acquisitionDimension').onchange=()=>ctx.route();
 $('exportAcquisition').onclick=()=>downloadReport([['Group','Visitors','Visits','Pageviews','Events','Revenue (separate currencies)'],...reportRows.map(r=>[r.value,r.metrics.visitors,r.metrics.visits,r.metrics.pageviews,r.metrics.events,revenue(r.metrics.revenue)])],ctx.site().id+'-acquisition.csv');
 async function allSites(run){
  const list=ctx.sites(),results=[];$('allSitesNote').textContent='Loading permitted websites…';
  for(let start=0;start<list.length;start+=3){const chunk=await Promise.all(list.slice(start,start+3).map(async site=>{try{return {site,data:await call('report',{...ctx.request(),site:site.id,filters:[],dimension:''})};}catch(e){return {site,error:e.message};}}));if(!alive(run))return;results.push(...chunk);}
  let visitors=0n,visits=0n,views=0n;for(const r of results)if(r.data){visitors+=r.data.totals.visitors;visits+=r.data.totals.visits;views+=r.data.totals.pageviews;}
  const failed=results.filter(r=>r.error).length;
  $('allSitesMetrics').innerHTML=[['Site visitor estimates',visitors],['Visits',visits],['Pageviews',views]].map(([name,n])=>`<div class="metric"><span class="subtle">${name}</span><strong class="value">${num(n)}</strong></div>`).join('');
  $('allSitesNote').textContent=(failed?`${failed} website report(s) unavailable. Totals below are partial. `:'')+'Visitors are summed per website and day, not deduplicated people across websites. Website filters do not apply here.';
  $('allSitesRows').innerHTML=results.map(r=>`<div class="data-row"><button class="text-button" data-open-site="${esc(r.site.id)}">${esc(r.site.name)}<span class="subtle"> · ${esc(r.site.domain)}</span></button><span>${r.error?esc(r.error):num(r.data.totals.pageviews)+' views · '+num(r.data.totals.events)+' events · '+esc(revenue(r.data.totals.revenue))}</span></div>`).join('');
 }
 $('allSitesRows').onclick=e=>{const b=e.target.closest('[data-open-site]');if(b)ctx.openSite(b.dataset.openSite);};
 async function revenueView(run){const d=$('revenueDimension').value,r=ctx.request(d,1000),data=await call('report',r);if(!alive(run))return;$('revenueTotal').textContent=revenue(data.totals.revenue);$('revenueRows').innerHTML=fullTable(data.rows.filter(r=>r.metrics.revenue.length),d);$('revenueNote').textContent='Recorded event revenue · currencies remain separate · visit-first attribution'+(data.truncated?' · top 1,000 traffic groups only; low-volume revenue groups may be omitted':'');}
 $('revenueDimension').onchange=()=>ctx.route();
 async function searchSettings(run){const config=await call('searchConnection',ctx.site().id);if(!alive(run))return;connection=config;$('googleClientId').value=connection.clientId;$('googleProperty').innerHTML=`<option value="sc-domain:${esc(ctx.site().domain)}">Domain: ${esc(ctx.site().domain)}</option><option value="https://${esc(ctx.site().domain)}/">URL prefix: https://${esc(ctx.site().domain)}/</option>`;$('googleProperty').value=connection.property||'sc-domain:'+ctx.site().domain;$('googleOrigin').textContent=location.origin;$('googleConnectionStatus').textContent=connection.clientId?'Ready for Google authorization. Refresh SEO from Acquisition.':'One-time setup by your IT team.';}
 $('googleConnectionForm').oninput=()=>ctx.dirty(true);
 $('googleConnectionForm').onsubmit=async e=>{e.preventDefault();const run=ctx.epoch(),button=e.submitter;button.disabled=true;try{const config=await call('saveSearchConnection',ctx.site().id,{clientId:$('googleClientId').value.trim(),property:$('googleProperty').value,revision:connection.revision});if(alive(run)){preparedSearch=null;connection=config;ctx.dirty(false);$('googleConnectionStatus').textContent='Saved. Open Acquisition → Search Console to authorize and load a report.';ctx.notice('Search Console connection saved.','success');}}catch(e){if(alive(run))showError(e);}finally{button.disabled=false;}};
 $('disconnectGoogle').onclick=async()=>{const run=ctx.epoch(),site=ctx.site().id,revision=connection?.revision;if(revision===undefined)return;if(!await ctx.confirm('Disconnect Search Console?','The saved SEO report will be removed. Google access tokens are not stored in Crumbs.','Disconnect'))return;try{await call('saveSearchConnection',site,{clientId:'',property:'',revision});if(!alive(run))return;preparedSearch=null;ctx.dirty(false);await searchSettings(run);ctx.notice('Disconnected and saved SEO data removed.','success');}catch(e){showError(e);}};
 async function searchView(run){
  const data=await call('searchSnapshot',ctx.site().id);if(!alive(run))return;const s=data[0];$('searchMetrics').innerHTML='';$('searchQueries').innerHTML='';$('searchPages').innerHTML='';
  if(!s){$('searchNote').textContent='Connect Google Search Console under Settings, then refresh a report. Google search clicks are separate from Crumbs visits.';return;}
  const iso=n=>new Date(Number(n)*1000).toISOString().slice(0,10),m=s.totals;
  $('searchNote').textContent=`Saved Google report for ${s.property}: ${iso(s.from)} – ${iso(s.until-1n)} · Google uses Pacific Time · refreshed ${new Date(Number(s.fetchedAt)*1000).toLocaleString()}. This snapshot keeps its own dates and ignores Crumbs filters. Google omits some queries; listed rows do not necessarily sum to totals.${s.truncated?' Top 1,000 rows only.':''}`;
  $('searchMetrics').innerHTML=[['Google clicks',num(m.clicks)],['Impressions',num(m.impressions)],['Click-through rate',rate(m.clicks,m.impressions)],['Average position',Number(m.impressions)?(Number(m.positionMilli)/1000).toFixed(1):'—']].map(([name,n])=>`<div class="metric"><span class="subtle">${name}</span><strong class="value">${n}</strong></div>`).join('');
  const rows=list=>list.length?`<div class="table-scroll"><table class="analytics-table"><thead><tr><th>Result</th><th>Clicks</th><th>Impressions</th><th>CTR</th><th>Position</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.value)}</td><td>${num(r.clicks)}</td><td>${num(r.impressions)}</td><td>${rate(r.clicks,r.impressions)}</td><td>${(Number(r.positionMilli)/1000).toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-report">No rows saved. Search terms are optional.</p>';
  $('searchQueries').innerHTML=rows(s.queries);$('searchPages').innerHTML=rows(s.pages);
 }
 $('refreshSearch').onclick=async()=>{const button=$('refreshSearch'),run=ctx.epoch(),version=++requestVersion,site=ctx.site(),r=ctx.request();button.disabled=true;$('searchProgress').textContent='Preparing Google authorization…';try{if(r.until-r.from<86400n||r.until-r.from>366n*86400n)throw new Error('Choose calendar dates between 1 and 366 days before refreshing Search Console. Google does not provide realtime reports.');if(!preparedSearch||preparedSearch.site!==site.id||!window.google?.accounts?.oauth2){const config=await call('searchConnection',site.id);if(!alive(run)||version!==requestVersion)return;if(!config.clientId||!config.property)throw new Error('Complete Search Console setup in Settings first.');await loadGoogle();if(alive(run)){preparedSearch={site:site.id,config};button.textContent='Continue with Google';$('searchProgress').textContent='Google sign-in is ready for '+config.property+'. Continue to choose your Google account.';}return;}const config=preparedSearch.config;const token=await authorize(config.clientId);if(!alive(run)||version!==requestVersion)return;$('searchProgress').textContent='Reading finalized Google search statistics…';const snapshot=await fetchSearchReport({token,site,connection:config,from:r.from,until:r.until,includeQueries:$('includeSearchTerms').checked});if(!alive(run)||version!==requestVersion)return;await call('saveSearchSnapshot',config.revision,snapshot);if(!alive(run))return;await searchView(run);button.textContent='Connect Google & refresh';$('searchProgress').textContent='Search report refreshed. No Google access token was saved.';}catch(e){if(alive(run)){preparedSearch=null;button.textContent='Connect Google & refresh';$('searchProgress').textContent=e.message;}}finally{button.disabled=false;}};
 function clear(){requestVersion++;preparedSearch=null;saved=[];connection=null;reportRows=[];for(const id of ['savedReportList','acquisitionRows','searchMetrics','searchQueries','searchPages','searchNote','searchProgress','allSitesMetrics','allSitesRows','allSitesNote','revenueRows','revenueTotal'])$(id).textContent='';$('saveReportForm').hidden=true;$('savedReportList').hidden=true;$('savedReport').innerHTML='<option value="">Saved filters & funnels</option>';}
 return {savedControls,acquisition,allSites,revenueView,searchSettings,searchView,clear};
}
